#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_clear_valid_vector(void) {
    // Setup: create a valid non-empty vector
    Vector* vec = (Vector*)malloc(sizeof(Vector));
    TEST_ASSERT_NOT_NULL(vec);
    int init_result = init(vec, 5);
    TEST_ASSERT_EQUAL_INT(0, init_result);

    // Fill vector with some data to ensure it has contents to clear
    int values[] = {10, 20, 30};
    for (int i = 0; i < 3; i++) {
        int push_result = push(vec, values[i]);
        TEST_ASSERT_EQUAL_INT(0, push_result);
    }

    // Verify vector has data before clear
    TEST_ASSERT_EQUAL_INT(3, vector_length(vec));

    // Test: call clear on valid vector
    int result = clear(vec);
    TEST_ASSERT_EQUAL_INT(0, result);

    // Assertions: vector should be empty but valid
    TEST_ASSERT_EQUAL_INT(0, vector_length(vec));
    TEST_ASSERT_EQUAL_INT(1, vector_is_empty(vec));

    // Cleanup
    if (vec != NULL) {
        delete(vec);
        free(vec);
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_clear_valid_vector);
    return UNITY_END();
}

